from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    base = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def mode(values):
        return Counter(values).most_common(1)[0][0]

    row_modes = [mode(row) for row in grid]
    col_modes = [mode(grid[r][c] for r in range(h)) for c in range(w)]

    rows = [r for r, v in enumerate(row_modes) if v != base]
    cols = [c for c, v in enumerate(col_modes) if v != base]

    if len(rows) < 2 or len(cols) < 2:
        return [[base]]

    line_color = Counter(
        [row_modes[r] for r in rows] + [col_modes[c] for c in cols]
    ).most_common(1)[0][0]

    out = []
    for i in range(len(rows) - 1):
        row = []
        for j in range(len(cols) - 1):
            vals = (
                grid[rows[i]][cols[j]],
                grid[rows[i]][cols[j + 1]],
                grid[rows[i + 1]][cols[j]],
                grid[rows[i + 1]][cols[j + 1]],
            )
            if vals[0] == vals[1] == vals[2] == vals[3] and vals[0] not in (base, line_color):
                row.append(vals[0])
            else:
                row.append(base)
        out.append(row)

    # A colored terminal grid line can itself encode the final output row.
    anomalous_rows = [
        r for r in rows
        if any(grid[r][c] not in (base, line_color) for c in cols)
    ]
    if anomalous_rows:
        last = anomalous_rows[-1]
        if last in rows[:-1]:
            i = rows.index(last)
            if all(v == base for v in out[i]):
                for j in range(len(cols) - 1):
                    a, b = grid[last][cols[j]], grid[last][cols[j + 1]]
                    if a == b and a not in (base, line_color):
                        out[i][j] = a

    # Remove unused outer rows and columns.
    while out and all(v == base for v in out[0]):
        out.pop(0)
    while out and all(v == base for v in out[-1]):
        out.pop()
    if not out:
        return [[base]]

    while out[0] and all(row[0] == base for row in out):
        for row in out:
            row.pop(0)
    while out[0] and all(row[-1] == base for row in out):
        for row in out:
            row.pop()

    return out
